export function renderUnit(unit: string) {
  if (unit.startsWith('fm://')) {
    return 'fm'
  }
  return unit
}

/** fm://<owner>/<repo>/<path> 형태의 unit_name을 파싱한다. fm:// 가 아니면 null. */
export function parseFmUrl(
  unitName: string
): { owner: string; repo: string; path?: string } | null {
  if (!unitName.startsWith('fm://')) return null
  const parts = unitName.replace('fm://', '').split('/')
  if (parts.length < 2) return null
  return {
    owner: parts[0],
    repo: parts[1],
    path: parts.length > 2 ? parts.slice(2).join('/') : undefined,
  }
}

/** fm:// 계획 이름 형식: 폴더 마지막 이름 / 폴더 전체 경로 / 레포를 포함한 경로. */
export type FmPlanNameKind = 'name' | 'folder' | 'repo'

export const FM_PLAN_NAME_KINDS: { kind: FmPlanNameKind; label: string }[] = [
  { kind: 'name', label: '이름' },
  { kind: 'folder', label: '폴더' },
  { kind: 'repo', label: '레포' },
]

/**
 * fm:// unit_name 으로 계획 이름을 만든다. fm:// 가 아니면 null.
 * 경로가 없으면(레포 루트) name/folder 는 repo 이름이 된다.
 */
export function getFmPlanName(unitName: string, kind: FmPlanNameKind): string | null {
  const fm = parseFmUrl(unitName)
  if (!fm) return null
  const { repo, path } = fm
  if (!path) return repo
  switch (kind) {
    case 'name':
      return path.split('/').pop()!
    case 'folder':
      return path
    case 'repo':
      return `${repo}/${path}`
  }
}

/**
 * 두 fm:// unit_name 이 같은 디렉터리이거나 상하위 관계인지 판정한다.
 * fin 이력 하나가 두 플랜에 동시에 매칭되는 조합이 true 다.
 * (DB 트리거 check_fm_plan_path_overlap 과 같은 규칙; 018 마이그레이션 참고)
 */
export function isFmPathOverlap(a: string, b: string): boolean {
  if (!a.startsWith('fm://') || !b.startsWith('fm://')) return false
  if (a === b) return true
  return a.startsWith(b + '/') || b.startsWith(a + '/')
}
